protocol.scriptContent:
// LIV-01: event 2, two-plate cycle with a third-plate STACK transfer overlapping the F.A.S.T. liquid leg (lanes).
// Every input is validated and every parameter object is built BEFORE the first galago call,
// so a bad input throws with nothing queued. No fallback values live here: defaults are the
// parameter defaults shown in the run form. The F.A.S.T. rules mirror _check_args in
// tools/fast/server.py (deck 1-6, ids / columns / rows >= 1, 1-2 letter rows, volume > 0,
// tip_reuse fresh or reuse); keep the two in step.
function text(name) {
  var v = params[name];
  return v === undefined || v === null ? "" : String(v).trim();
}
function need(name) {
  var v = text(name);
  if (v === "") { throw new Error("LIV-01: parameter '" + name + "' is required"); }
  return v;
}
function whole(name) {
  var n = Number(need(name));
  if (!isFinite(n) || Math.floor(n) !== n) { throw new Error("LIV-01: parameter '" + name + "' must be a whole number"); }
  if (n < -2147483648 || n > 2147483647) { throw new Error("LIV-01: parameter '" + name + "' must fit a 32-bit integer"); }
  return n;
}
function wholeBetween(name, min, max) {
  var n = whole(name);
  if (n < min || n > max) { throw new Error("LIV-01: parameter '" + name + "' must be a whole number from " + min + " to " + max); }
  return n;
}
function letters(name) {
  var v = need(name);
  var ok = v.length >= 1 && v.length <= 2;
  for (var i = 0; ok && i < v.length; i++) { ok = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".indexOf(v.charAt(i)) >= 0; }
  if (!ok) { throw new Error("LIV-01: parameter '" + name + "' must be one or two letters"); }
  return v;
}
function oneOf(name, allowed) {
  var v = need(name);
  if (allowed.indexOf(v) < 0) { throw new Error("LIV-01: parameter '" + name + "' must be one of " + allowed.join(", ")); }
  return v;
}
function positive(name) {
  var n = Number(need(name));
  if (!isFinite(n) || n <= 0) { throw new Error("LIV-01: parameter '" + name + "' must be a number above 0"); }
  return n;
}
function fastStep() {
  var p = {};
  var decks = ["source_deck", "dest_deck"];
  for (var d = 0; d < decks.length; d++) { p[decks[d]] = wholeBetween("fast_step_" + decks[d], 1, 6); }
  var ints = ["source_plate_id", "dest_plate_id", "source_start_col", "dest_start_col", "num_rows", "num_cols"];
  for (var i = 0; i < ints.length; i++) { p[ints[i]] = wholeBetween("fast_step_" + ints[i], 1, 2147483647); }
  p.source_start_row = letters("fast_step_source_start_row");
  p.dest_start_row = letters("fast_step_dest_start_row");
  p.volume = positive("fast_step_volume");
  p.tip_reuse = oneOf("fast_step_tip_reuse", ["fresh", "reuse"]);
  if (text("fast_step_expected_tray_id") !== "") { p.expected_tray_id = whole("fast_step_expected_tray_id"); }
  return p;
}
function toolKey(name) { return String(name || "").toLowerCase().replace(/[^a-z0-9]/g, ""); }

// Step key base: label (cut to 20 code points) + queue-time timestamp + 8 hex random.
// Computed once per run; every STACK leg gets its own suffix so two legs never merge.
var label = Array.from(need("batch_label")).slice(0, 20).join("");
var rand = (Math.random().toString(16) + "00000000").slice(2, 10);
var base = label + "-" + new Date().toISOString() + "-" + rand;

// A STACK location: device, deck, nest (byte-exact, trimmed) and an optional transfer profile.
function loc(prefix, profileParam) {
  return {
    device: need(prefix + "_device"),
    deck: need(prefix + "_deck"),
    nest: need(prefix + "_nest"),
    profile: profileParam ? text(profileParam) : ""
  };
}
function sameLoc(a, b) { return a.device === b.device && a.deck === b.deck && a.nest === b.nest; }

// STACK parameter object. key null builds a get_transfer_estimate object (no step_key);
// timeout null sends no timeout_s.
function stackParams(from, to, key, timeout) {
  var p = {};
  if (key !== null) { p.step_key = key; }
  p.robot = need("robot");
  p.labware_profile = need("labware_profile");
  p.source_device = from.device;
  p.source_deck = from.deck;
  p.source_nest = from.nest;
  if (from.profile !== "") { p.source_transfer_profile = from.profile; }
  p.destination_device = to.device;
  p.destination_deck = to.deck;
  p.destination_nest = to.nest;
  if (to.profile !== "") { p.destination_transfer_profile = to.profile; }
  if (timeout !== null) { p.timeout_s = timeout; }
  return p;
}

var stackTool = need("stack_tool");
var fastTool = need("fast_tool");
if (toolKey(stackTool) === toolKey(fastTool)) { throw new Error("LIV-01: parameter 'fast_tool' must differ from 'stack_tool'"); }

var plate1 = loc("plate1", "transfer_profile");
var plate2 = loc("plate2", "transfer_profile");
var tray1 = loc("tray1", "transfer_profile");
var tray2 = loc("tray2", "transfer_profile");
var spareA = loc("spare_a", "spare_a_transfer_profile");
var spareB = loc("spare_b", "spare_b_transfer_profile");

// D-02 spare guard: the overlap move is spare A to spare B only. It must never touch a plate
// home, the F.A.S.T. side, or be a no-op. Compared byte-exact like the manager.
if (sameLoc(spareA, spareB)) { throw new Error("LIV-01: spare A and spare B must differ"); }
if (sameLoc(spareA, plate1) || sameLoc(spareA, plate2) || sameLoc(spareB, plate1) || sameLoc(spareB, plate2)) {
  throw new Error("LIV-01: a spare nest must not be a plate home");
}
if (spareA.device === tray1.device || spareA.device === tray2.device || spareB.device === tray1.device || spareB.device === tray2.device) {
  throw new Error("LIV-01: a spare nest must not be on the F.A.S.T.-side device");
}

var cycleTimeout = text("stack_timeout_s") !== "" ? positive("stack_timeout_s") : null;
var fastParams = fastStep();
var legIn1 = stackParams(plate1, tray1, base + "-in1", cycleTimeout);
var legIn2 = stackParams(plate2, tray2, base + "-in2", cycleTimeout);
var legOut1 = stackParams(tray1, plate1, base + "-out1", cycleTimeout);
var legOut2 = stackParams(tray2, plate2, base + "-out2", cycleTimeout);
// Event 2 (motion): a third plate moves spare A to spare B during the F.A.S.T. leg and
// returns after the out1 barrier, so the rig ends where it started (D-03).
var overlapTimeout = null;
if (text("overlap_timeout_s") !== "") {
  var ot = Number(text("overlap_timeout_s"));
  if (!isFinite(ot) || ot < 0) { throw new Error("LIV-01: parameter 'overlap_timeout_s' must be a number at or above 0"); }
  overlapTimeout = ot;
}
var legX1 = stackParams(spareA, spareB, base + "-x1", overlapTimeout);
var legX2 = stackParams(spareB, spareA, base + "-x2", overlapTimeout);

galago.note("LIV-01 key base " + base);
galago.command(stackTool, "transfer", legIn1);
galago.command(stackTool, "transfer", legIn2);
galago.lane("fast");
galago.command(fastTool, "transfer", fastParams, { barrier: true });
// The lane is sticky: reset to primary or the overlap step would queue behind the F.A.S.T. step.
galago.lane();
galago.command(stackTool, "transfer", legX1);
galago.command(stackTool, "transfer", legOut1, { barrier: true });
galago.command(stackTool, "transfer", legOut2);
galago.command(stackTool, "transfer", legX2);
